class Solution {
public:
    int assignBikes(vector<vector<int>>& workers,
                    vector<vector<int>>& bikes) {
        int w = workers.size();
        int b = bikes.size();
        int states = 1 << b;
        vector<int> dp(states, INT_MAX / 4);
        dp[0] = 0;
        int answer = INT_MAX;
        for (int mask = 0; mask < states; ++mask) {
            int worker = __builtin_popcount(static_cast<unsigned>(mask));
            if (worker == w) {
                answer = min(answer, dp[mask]);
                continue;
            }
            if (worker > w || dp[mask] == INT_MAX / 4) {
                continue;
            }
            for (int bike = 0; bike < b; ++bike) {
                if ((mask & (1 << bike)) == 0) {
                    int distance = abs(workers[worker][0] - bikes[bike][0])
                                 + abs(workers[worker][1] - bikes[bike][1]);
                    int next = mask | (1 << bike);
                    dp[next] = min(dp[next], dp[mask] + distance);
                }
            }
        }
        return answer;
    }
};
